func (c *Core) DropCollection(ctx context.Context, in *milvuspb.DropCollectionRequest) (*commonpb.Status, error) {
	...
	if err := c.broadcastDropCollectionV1(ctx, in); err != nil {
		if errors.Is(err, errIgnoredDropCollection) {
			// collection or database not found, return success (idempotent drop)
			return commonpbutil.SuccessStatus(), nil  // <-- KEY: converts error to success
		}
		return merr.Status(err), nil
	}
	return commonpbutil.SuccessStatus(), nil
}

